ALTER TABLE public.medicaciones ADD COLUMN IF NOT EXISTS detalle jsonb NOT NULL DEFAULT '{}'::jsonb;
COMMENT ON COLUMN public.medicaciones.detalle IS 'Structured medication configuration; legacy dose, frequency and notes retained without inference.';
CREATE TABLE public.medication_schedules (medication_id uuid PRIMARY KEY REFERENCES public.medicaciones(id) ON DELETE CASCADE, user_id uuid NOT NULL, config jsonb NOT NULL DEFAULT '{}'::jsonb);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.medication_schedules TO authenticated; GRANT ALL ON public.medication_schedules TO service_role;
ALTER TABLE public.medication_schedules ENABLE ROW LEVEL SECURITY;
CREATE POLICY schedules_owner ON public.medication_schedules FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.medicaciones m WHERE m.id=medication_id AND m.user_id=auth.uid()));
CREATE TABLE public.medication_doses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), medication_id uuid NOT NULL REFERENCES public.medicaciones(id) ON DELETE CASCADE, user_id uuid NOT NULL, scheduled_at timestamptz NOT NULL, status text NOT NULL CHECK (status IN ('tomada','omitida','pospuesta')), recorded_at timestamptz NOT NULL DEFAULT now(), postponed_until timestamptz, UNIQUE(medication_id,scheduled_at));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.medication_doses TO authenticated; GRANT ALL ON public.medication_doses TO service_role;
ALTER TABLE public.medication_doses ENABLE ROW LEVEL SECURITY;
CREATE POLICY doses_owner ON public.medication_doses FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.medicaciones m WHERE m.id=medication_id AND m.user_id=auth.uid()));
CREATE TABLE public.medication_symptoms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), medication_id uuid NOT NULL REFERENCES public.medicaciones(id) ON DELETE CASCADE, user_id uuid NOT NULL, occurred_at timestamptz NOT NULL, symptom text NOT NULL, severity text NOT NULL CHECK(severity IN ('leve','moderada','grave')), recent_dose boolean NOT NULL DEFAULT false, notes text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.medication_symptoms TO authenticated; GRANT ALL ON public.medication_symptoms TO service_role;
ALTER TABLE public.medication_symptoms ENABLE ROW LEVEL SECURITY;
CREATE POLICY symptoms_owner ON public.medication_symptoms FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.medicaciones m WHERE m.id=medication_id AND m.user_id=auth.uid()));
CREATE TABLE public.notification_prefs (user_id uuid PRIMARY KEY, allergies text NOT NULL DEFAULT '', health_consent boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.notification_prefs TO authenticated; GRANT ALL ON public.notification_prefs TO service_role;
ALTER TABLE public.notification_prefs ENABLE ROW LEVEL SECURITY;
CREATE POLICY medication_prefs_owner ON public.notification_prefs FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.notification_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, medication_id uuid NOT NULL REFERENCES public.medicaciones(id) ON DELETE CASCADE, scheduled_at timestamptz NOT NULL, channel text NOT NULL CHECK(channel IN ('email','whatsapp')), attempt integer NOT NULL DEFAULT 0 CHECK(attempt BETWEEN 0 AND 1), status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(medication_id,scheduled_at,channel,attempt));
GRANT SELECT,DELETE ON public.notification_log TO authenticated; GRANT ALL ON public.notification_log TO service_role;
ALTER TABLE public.notification_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_log_read_owner ON public.notification_log FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY notification_log_delete_owner ON public.notification_log FOR DELETE TO authenticated USING(user_id=auth.uid());